developer_name = "Rahul"
language = "Python"
experience = 1
languages = ["Python", "JavaScript", "Java", "Go"]

def show_menu():
    print("1. Show developer information")
    print("2. Show supported languages")
    print("3. Check username")
    print("4. Show project health")
    print("5. Exit")

while True:
    show_menu()
    choice = input()

    if choice == "1":
        print(f"Developer: {developer_name}")
        print(f"Language: {language}")
        print(f"Experience: {experience} year")
    elif choice == "2":
        for item in languages:
            print(item)
    elif choice == "3":
        username = input()
        if len(username) >= 3 and " " not in username:
            print("Valid username")
        else:
            print("Invalid username")
    elif choice == "4":
        total_files = 20
        test_files = 8
        coverage = (test_files / total_files) * 100

        if coverage >= 30:
            print("Good test coverage")
        else:
            print("Test coverage needs improvement")
    elif choice == "5":
        break
    else:
        print("Invalid choice")
